CREATE TABLE IF NOT EXISTS public.blog_public_metadata (id TEXT PRIMARY KEY, data JSONB NOT NULL CHECK(jsonb_typeof(data)='object'), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
INSERT INTO public.blog_public_metadata(id,data) VALUES ('editorial','{"site":{"id":"motazalqmi","name":"مدونة معتز العلقمي","tagline":"حيث تلتقي الكلمة بالفكر، ويزهر الأدب","description":"مدونة ثقافية تهتم باللغة والأدب والتاريخ والفكر والشعر العربي.","owner":"معتز العلقمي","credit":"برمجة وتطوير معتز العلقمي – تعز – اليمن – 2026م","officialUrl":"https://motazalqmi.vercel.app","shareUrlPattern":"https://motazalqmi.vercel.app/articles/{slug}","about":"انطلقت مدونة «معتز العلقمي» لتكون واحة عربية رصينة تعيد للكلمة المكتوبة هيبتها وجمالها، في زمن طغت فيه السرعة والسطحية. نؤمن بأن اللغة العربية ليست مجرد وعاء للتخاطب، بل هي هوية حضارية وفلسفة جمال متكاملة.\n\nتهدف المدونة إلى تقديم محتوى ثقافي وأدبي وتاريخي يجمع بين عمق الفكرة وفصاحة العبارة ومتعة التصميم البصري.","features":["المقالات","الأقسام","البحث","الاقتباسات","المحفوظات","القراءة دون إنترنت"]},"sections":[{"id":"general","title":"كتابات عامة","subtitle":"مقالات وتأملات وموضوعات متنوعة في الفكر والحياة"},{"id":"quotes","title":"اقتباسات","subtitle":"مختارات من العبارات الأدبية والفكرية الملهمة"},{"id":"books","title":"من بطون الكتب","subtitle":"مقتطفات وقراءات ومراجعات من كنوز المؤلفات"},{"id":"pens","title":"من وحي الأقلام","subtitle":"نصوص إبداعية وخواطر ومقالات بأسلوب أدبي رفيع"},{"id":"news","title":"أحاديث وأخبار","subtitle":"موضوعات ثقافية وأخبار أدبية ومحطات تاريخية"},{"id":"wisdom","title":"حكم ومواعظ","subtitle":"درر الحكمة والتجارب الإنسانية العميقة عبر العصور"},{"id":"arabic_lit","title":"أدبنا العربي","subtitle":"الشعر العربي واللغة والبلاغة والأدباء والتراث"},{"id":"about","title":"حول المدونة","subtitle":"تعريف برسالة المدونة وصاحبها وأهدافها الثقافية"}],"quotes":[{"text":"إنَّ الكلامَ لفي الفؤادِ وإنَّما ... جُعِلَ اللسانُ على الفؤادِ دليلا","author":"يُنسب إلى الأخطل التغلبي","source":"من الشعر العربي"},{"text":"خيرُ جليسٍ في الزمانِ كتابُ ... تَلهو بهِ إنْ خانَكَ الأصحابُ","author":"أبو الطيب المتنبي","source":"الديوان"},{"text":"البيانُ بصرٌ، والعيُّ عمى، كما أنَّ العلمَ بصرٌ والجهلَ عمى.","author":"أبو عثمان الجاحظ","source":"البيان والتبيين"},{"text":"وما الفضلُ إلا لأهلِ العلمِ إنَّهمُ ... على الهُدى لِمَنِ استهدى أدلّاءُ","author":"يُنسب إلى الإمام الشافعي","source":"منسوب إلى ديوانه"}]}'::jsonb) ON CONFLICT(id) DO NOTHING;
